import {CASES,CASE_SOURCES} from './cases.js';
import {SOURCES} from './content.js';
import {caseById,freshCase,caseReady,submitCase,nextCaseStep,resetCase,caseScore} from './case-engine.js';
export function createCaseUI({getState,save,go,refresh,e,btn,icon}){
 let selected=CASES[0].id,filter='Todos',collection='word',search='',limit=24,reviewOnly=false;
 const work=()=>{const s=getState();s.casework??={};return s.casework;};
 const current=()=>work()[selected]??(work()[selected]=freshCase());
 const refs=c=>`<div class="source">${c.refs.map(([k,a])=>`<a href="${SOURCES[k].url}" target="_blank" rel="noopener noreferrer">${e(SOURCES[k].name)} · ${e(a)}</a>`).join('<br>')}</div>`;
 const origin=c=>`<p class="case-origin"><b>${c.collection==='word'?'MATERIAL PRINCIPAL · WORD':'PRÁCTICA EXTRA · '+(c.source==='actividad'?'PDF / APUNTE':'POWERPOINT')}</b><br>${e(CASE_SOURCES[c.source])}<br>${e(c.location)}</p>`;
 const answer=(s,v=s.answer)=>s.type==='reason'?v:s.type==='number'?`${v} ${s.unit}`:Array.isArray(v)?v.map(i=>s.options[i]).join(' · '):s.options[v];
 const paras=t=>String(t).split('\n').map(x=>`<p>${e(x)}</p>`).join('');
 const questions=qs=>`<ol class="original-questions">${qs.map(q=>`<li>${e(q)}</li>`).join('')}</ol>`;
 function list(){const w=work(),pool=CASES.filter(c=>c.collection===collection),done=pool.filter(c=>w[c.id]?.answers.length===c.steps.length).length,norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const found=pool.filter(c=>(filter==='Todos'||filter===c.topic)&&(!reviewOnly||w[c.id]?.status==='review')&&norm([c.title,c.facts,c.location,...(c.questions||[])].join(' ')).includes(norm(search)));
 return `<div class="narrow"><div class="page-head"><span class="eyebrow">LABORATORIO DE CASOS</span><h1>Leé, decidí y fundamentá.</h1><p class="muted">130 casos de los Word de tu materia, con sus 410 consignas. Los ejercicios de presentaciones anteriores están separados como práctica extra.</p></div><div class="case-collections" role="group" aria-label="Fuente de los casos">${btn('Casos de los Word · 130','case-collection:word',collection==='word'?'primary':'secondary',`aria-pressed="${collection==='word'}"`)}${btn('Práctica extra · 25','case-collection:extra',collection==='extra'?'primary':'secondary',`aria-pressed="${collection==='extra'}"`)}</div><div class="case-overview"><b>${done} / ${pool.length} fichas completadas</b><span class="small">${collection==='word'?'50 de Obligaciones · 40 de Contratos · 10 de Unidad 4 · 30 de Unidad 5':'23 casos y 2 talleres de los PPT anteriores y la actividad de pagaré. No son los casos de los seis Word.'}</span></div><label class="small" for="case-search">Buscar un caso, un nombre o un concepto</label><input id="case-search" class="case-search" type="search" data-case-input="search" value="${e(search)}" placeholder="Ej.: seña, María, caso 10…"><div class="case-filters" role="group" aria-label="Filtrar por tema">${['Todos',...new Set(pool.map(c=>c.topic))].map(t=>btn(e(t),`case-filter:${t}`,`case-filter ${filter===t?'selected':''}`,`aria-pressed="${filter===t}"`)).join('')}${btn('Marcados para repasar','case-review-filter',`case-filter ${reviewOnly?'selected':''}`,`aria-pressed="${reviewOnly}"`)}</div><p class="small muted" role="status">${found.length} resultados · ${Math.min(limit,found.length)} visibles</p><div class="case-catalog">${found.slice(0,limit).map(c=>{const r=w[c.id],done=r?.answers.length===c.steps.length;return `<article class="case-card"><div class="chips"><span class="chip">${e(c.topic)}</span>${r?.status==='review'?'<span class="chip">Para repasar</span>':done?'<span class="chip case-done">Completado</span>':''}</div><h2>${e(c.title)}</h2>${origin(c)}<div class="case-card-foot"><span class="small muted">${c.questions?`${c.questions.length} ${c.questions.length===1?'consigna':'consignas'} · decisión + desarrollo`:`${c.steps.length} pasos`}</span>${btn(done?'Ver mi trabajo':r?'Continuar':'Resolver',`case-open:${c.id}`,'secondary')}</div></article>`;}).join('')||'<div class="empty">No hay casos con estos filtros.</div>'}</div>${found.length>limit?btn('Mostrar 24 más','case-more','secondary stretch'):''}<details class="panel case-method"><summary>Fuentes, numeración y método</summary><p>El material principal conserva hechos y consignas de seis Word: Unidad 1, 50 casos; Unidad 3, 40; Unidad 4, 10; locación, leasing y comodato, 10 cada uno. Los primeros 30 de Unidad 1 se identifican por orden y rangos del archivo. Unidad 3 salta de 20 a 30: respetamos su numeración.</p><p>Cada ficha agrega una decisión o cálculo y un desarrollo. Las consignas originales siguen completas. La guía es una orientación elaborada para estudiar, no una solución oficial. Explicita datos faltantes y corrige premisas normativas que no se sostienen.</p><p>Tu escrito no se corrige automáticamente ni recibe nota. Compará hechos, regla, aplicación y conclusión, y marcá lo que quieras repasar. La decisión breve sí tiene devolución automática. Los casos guardan avance propio y no suman XP.</p><p>La práctica extra conserva los 23 casos y 2 talleres anteriores con su fuente por ficha. No encontramos un Word específico de casos de Unidad 2 o 6 entre estos seis archivos. Las lecciones sí incluyen ambos temas dentro del alcance del parcial.</p></details></div>`;}
 function field(s,r,a){const v=a?.value??r.draft;return `<fieldset ${a?'disabled':''}><legend class="visually-hidden">Tu respuesta</legend>${s.type==='reason'?`<label for="case-reason" class="small">Tu razonamiento (mínimo 12 caracteres, sin corrección automática)</label><textarea id="case-reason" data-case-input="reason" rows="8" maxlength="6000" placeholder="1. Hecho → regla → aplicación → conclusión…">${e(v??'')}</textarea>`:s.type==='number'?`<label for="case-number" class="small">Importe en ${e(s.unit)}</label><input id="case-number" class="case-number" data-case-input="number" inputmode="decimal" value="${e(v??'')}"><p class="small muted">Coma o punto para decimales; sin separador de miles.</p>`:`${s.type==='multi'?'<p>Elegí todas las opciones correctas.</p>':''}<div class="options">${s.options.map((o,i)=>{const chosen=s.type==='multi'?v?.includes(i):v===i;return btn(`<span class="option-key">${s.type==='multi'?(chosen?'✓':'+'):i+1}</span><span>${e(o)}</span>`,`case-option:${i}`,`option ${chosen?'selected':''}`,`aria-pressed="${!!chosen}"`);}).join('')}</div>`}</fieldset>`;}
 function step(c,r,s,a){return `<section class="study-card case-step"><div class="case-step-head"><span class="chip">PASO ${r.index+1} DE ${c.steps.length}</span><span>${e(s.title)}</span></div><h2>${e(s.prompt)}</h2>${s.questions?questions(s.questions):''}${field(s,r,a)}${!a?`<div class="case-controls">${btn(r.hints.includes(r.index)?'Pista abierta':'Necesito una pista','case-hint','ghost',r.hints.includes(r.index)?'disabled':'')}${btn(s.type==='reason'?'Guardar y comparar':'Comprobar','case-check','primary',caseReady(s,r.draft)?'':'disabled')}</div>${r.hints.includes(r.index)?`<aside class="case-hint" role="status"><b>Pista</b><p>${e(s.hint)}</p></aside>`:''}`:`<section class="feedback ${a.ok===false?'bad':''}" role="status"><h3>${s.type==='reason'?'Compará con la guía orientativa':a.ok?'Decisión correcta.':'Revisemos el razonamiento.'}</h3>${s.type==='reason'?'<p class="small">No se evaluó tu escrito. Revisá cada consigna y los datos faltantes.</p>':!a.ok?`<p><b>Respuesta esperada:</b> ${e(answer(s))}</p>`:''}${paras(s.explanation)}${refs(c)}</section><div class="quiz-footer">${btn(r.index===c.steps.length-1?'Cerrar mi análisis':'Siguiente paso','case-next')}</div>`}</section>`;}
 function summary(c,r){const auto=c.steps.filter(s=>s.type!=='reason').length;return `<section class="study-card case-summary"><span class="eyebrow">TU ANÁLISIS</span><h2>Ficha completada</h2><p>${r.answers.filter(a=>a.ok===true).length} de ${auto} decisiones automáticas correctas · ${caseScore(r,c)}%.</p>${c.questions?'<p class="notice">Este porcentaje no evalúa tus respuestas escritas a las consignas del Word.</p>':''}<p class="small muted">${r.answers.filter(a=>a.hint).length} pasos con pista · mejor resultado automático: ${r.best}%.</p><label for="case-note"><h3>${e(c.reflection)}</h3></label><textarea id="case-note" data-case-input="note" rows="4" maxlength="3000" placeholder="La conclusión cambiaría si…">${e(r.note)}</textarea><details class="case-model"><summary>Guía de resolución del caso</summary>${paras(c.model)}</details><div class="case-revision"><h3>Sobre esta adaptación</h3><p>${e(c.revision)}</p>${refs(c)}</div><h3>Revisá tus respuestas</h3>${r.answers.map((a,i)=>{const s=c.steps[i];return `<details class="mistake"><summary>${a.ok===null?'✎':a.ok?'✓':'↗'} ${e(s.title)}</summary><p>${e(s.prompt)}</p>${s.questions?questions(s.questions):''}<div class="case-written"><b>Tu respuesta</b>${paras(answer(s,a.value))}</div><p><b>${a.ok===null?'Guía orientativa':'Respuesta esperada'}:</b> ${e(answer(s))}</p>${a.ok===null?'':paras(s.explanation)}</details>`;}).join('')}<h3>¿Cómo te sentís con este caso?</h3><div class="action-row">${btn('Quiero repasarlo','case-mark:review',r.status==='review'?'primary':'secondary',`aria-pressed="${r.status==='review'}"`)}${btn('Lo puedo explicar','case-mark:understood',r.status==='understood'?'primary':'secondary',`aria-pressed="${r.status==='understood'}"`)}</div><p class="small muted">Autoevaluación personal, sin calificación docente.</p><div class="action-row">${btn('Volver a los casos','nav:cases')}${btn('Practicar otra vez','case-retry','secondary')}</div><p class="small muted">Al repetir se reinician las respuestas del intento. Tu conclusión y mejor resultado se conservan.</p></section>`;}
 function detail(){const c=caseById[selected],r=current(),s=c.steps[r.index];return `<div class="narrow case-workspace">${btn(`${icon('left')} Todos los casos`,'nav:cases','back')}<div class="page-head"><span class="eyebrow">${c.questions?'CASO DEL WORD':'PRÁCTICA EXTRA'}</span><h1>${e(c.title)}</h1>${origin(c)}</div><section class="case-facts"><h2>El enunciado${c.questions?' original':''}</h2>${paras(c.facts)}${c.questions?`<details class="case-consignas"><summary>Ver las ${c.questions.length} consignas originales</summary>${questions(c.questions)}</details>`:''}</section>${s?step(c,r,s,r.answers[r.index]):summary(c,r)}</div>`;}
 function action(raw){if(!raw.startsWith('case-'))return false;const [cmd,id]=raw.split(':');if(cmd==='case-collection'){if(['word','extra'].includes(id))collection=id;filter='Todos';search='';limit=24;reviewOnly=false;refresh();return true;}if(cmd==='case-filter'){filter=id;limit=24;refresh();return true;}if(cmd==='case-review-filter'){reviewOnly=!reviewOnly;limit=24;refresh();return true;}if(cmd==='case-more'){limit+=24;refresh();return true;}if(cmd==='case-open'){if(caseById[id]){selected=id;current();save();go('case');}return true;}const c=caseById[selected],r=current(),s=c.steps[r.index];if(cmd==='case-mark'){if(['review','understood'].includes(id)){r.status=id;save();refresh();}return true;}if(cmd==='case-retry'){work()[selected]=resetCase(r);save();go('case');return true;}if(cmd==='case-next'){if(nextCaseStep(r,c)){save();go('case');}return true;}if(!s||r.answers[r.index])return true;if(cmd==='case-option'){const n=Number(id);if(!s.options||!Number.isInteger(n)||n<0||n>=s.options.length)return true;if(s.type==='multi'){const v=Array.isArray(r.draft)?r.draft:[];r.draft=v.includes(n)?v.filter(i=>i!==n):[...v,n];}else r.draft=n;save();refresh();}if(cmd==='case-hint'){if(!r.hints.includes(r.index))r.hints.push(r.index);save();refresh();}if(cmd==='case-check'&&submitCase(r,c)){save();refresh();}return true;}
 function input(ev){const t=ev.target,k=t.dataset?.caseInput;if(!k)return;if(k==='search'){search=t.value;limit=24;const pos=t.selectionStart;refresh();const el=document.querySelector('#case-search');el?.focus();if(el&&pos!==null)el.setSelectionRange(pos,pos);return;}const r=current();if(k==='note'){r.note=t.value.slice(0,3000);save();}if(['number','reason'].includes(k)&&!r.answers[r.index]){r.draft=t.value.slice(0,k==='reason'?6000:60);save();const check=document.querySelector('[data-action="case-check"]');if(check)check.disabled=!caseReady(caseById[selected].steps[r.index],r.draft);}}
 return {list,detail,action,input};
}
